# Pagamento multi-hop con HTLC: hash lock + timeout decrescenti
import hashlib

def sha(x: bytes) -> bytes:
    return hashlib.sha256(x).digest()

class HTLC:
    def __init__(self, payer, payee, amount, h, timeout):
        self.payer, self.payee, self.amount = payer, payee, amount
        self.h, self.timeout, self.state = h, timeout, "pending"

    def claim(self, preimage, day):
        if self.state == "pending" and day <= self.timeout and sha(preimage) == self.h:
            self.state = "paid"
        return self.state == "paid"

    def refund(self, day):
        if self.state == "pending" and day > self.timeout:
            self.state = "refunded"

def run(path, timeouts, amount, reveal_day, delay):
    R = b"segreto di Dave"
    H = sha(R)                                    # Dave manda H ad Alice
    htlcs = [HTLC(path[i], path[i+1], amount, H, timeouts[i]) for i in range(len(path)-1)]
    day = reveal_day                              # Dave rivela R all'ultimo hop
    for h in reversed(htlcs):                     # R si propaga all'indietro
        for x in htlcs:
            x.refund(day)                         # nel frattempo scadono i timeout
        h.claim(R, day)
        day += delay                              # tempo per reagire al prossimo hop
    net = {n: 0 for n in path}
    for h in htlcs:
        if h.state == "paid":
            net[h.payer] -= h.amount
            net[h.payee] += h.amount
    return [(h.payer + "->" + h.payee, h.timeout, h.state) for h in htlcs], net

path = ["Alice", "Bob", "Carol", "Dave"]
for label, t in [("decrescenti 20/15/10", [20, 15, 10]), ("uguali 10/10/10", [10, 10, 10])]:
    hops, net = run(path, t, 1, reveal_day=10, delay=2)
    print(label)
    for x in hops:
        print("  ", x)
    print("   saldo netto:", net)

# Routing con saldi: capacità (pubblica) vs saldo (privato)
from collections import deque

bal = {}   # bal[(u, v)] = saldo di u nel canale u-v
def channel(u, v, bu, bv):
    bal[(u, v)] = bu
    bal[(v, u)] = bv

channel("Alice", "Charlie", 6, 3)
channel("Charlie", "Bob", 6, 0)
channel("Charlie", "Eve", 1, 3)
channel("Eve", "Mary", 3, 1)
channel("Mary", "Bob", 3, 1)

def capacity(u, v):
    return bal[(u, v)] + bal[(v, u)]

def all_paths(src, dst):
    out, stack = [], [[src]]
    while stack:
        p = stack.pop()
        if p[-1] == dst:
            out.append(p); continue
        for (u, v) in bal:
            if u == p[-1] and v not in p:
                stack.append(p + [v])
    return sorted(out, key=len)

def feasible(path, amt, use_balance):
    hops = zip(path, path[1:])
    if use_balance:
        return all(bal[(u, v)] >= amt for u, v in hops)
    return all(capacity(u, v) >= amt for u, v in hops)

def pay(src, dst, amt):
    tried = 0
    for p in all_paths(src, dst):
        if not feasible(p, amt, use_balance=False):
            continue                      # scartato già guardando le capacità
        tried += 1
        if feasible(p, amt, use_balance=True):
            for u, v in zip(p, p[1:]):
                bal[(u, v)] -= amt
                bal[(v, u)] += amt
            return f"OK via {'->'.join(p)} (tentativi: {tried})"
    return f"FALLITO (tentativi: {tried})"

print("1)", pay("Alice", "Bob", 3))
print("2)", pay("Alice", "Bob", 3))
print("   saldi A-C:", bal[("Alice","Charlie")], bal[("Charlie","Alice")],
      " C-B:", bal[("Charlie","Bob")], bal[("Bob","Charlie")])
print("   capacità A-C:", capacity("Alice","Charlie"), " C-B:", capacity("Charlie","Bob"))
print("3)", pay("Charlie", "Bob", 3))
out = sum(bal[(u, v)] for (u, v) in bal if u == "Charlie")
print("   fondi totali di Charlie nei canali:", out)
